def get_fix_hint_for_unpinned(remediation: Dict[str, Any]) ->str:
    fix_version = remediation.get('recommended_version')
    spec = remediation.get('requirement')
    secure_options = remediation.get('other_recommended_versions', [])

    if not fix_version:
        return ""

    base_msg = f"Version {fix_version} has no known vulnerabilities and falls within your current specifier range."

    if not secure_options:
        return base_msg

    options_msg = build_other_options_msg(fix_version, True, secure_options)
    return f"{base_msg} {options_msg.lstrip()}"

def build_other_options_msg(fix_version: Optional[str], is_spec: bool,
    secure_options: List[str]) ->str:
    if not secure_options:
        return ""

    if len(secure_options) == 1:
        option_word = "Other version"
    else:
        option_word = "Other versions"

    options_str = ", ".join(secure_options)

    if is_spec:
        return f"{option_word} without known vulnerabilities is {options_str}"
    else:
        return f"{option_word} without known vulnerabilities are: {options_str}"
